func TestCorpusFieldDispositions(t *testing.T) {
	if len(fieldDispositions) != 166 {
		t.Fatal("the reviewed 166-case migration ledger is incomplete")
	}
	seen := map[string]bool{}
	for _, row := range fieldDispositions {
		key := row.Suite + "/" + row.ID
		if seen[key] || row.Owner == "" || row.Property == "" {
			t.Fatal("duplicate or unresolved field disposition", key)
		}
		seen[key] = true
	}
	corpusJSON(t, filepath.Join(t.ArtifactDir(), "field-dispositions.json"), fieldDispositions)
}
